function findMostFrequentFromMap(pairs) {
  if (pairs.length === 0) return null;
  const map = new Map(pairs);
  let maxKey = null;
  let maxCount = -Infinity;
  for (const [key, count] of map) {
    if (count > maxCount) {
      maxCount = count;
      maxKey = key;
    }
  }
  return maxKey;
}

